from collections import deque
# state (robot row 0..4, beam 0..5, tuple object (color,row,slot)); slots x=18+6s
# Horizontal right: beam+1, each object current row whose slot <= new beam shifts right if next cell unoccupied, process right-to-left
# Left: beam-1, objects current row whose slot <= old beam shift left, process left-to-right
# Vertical: objects at old row within beam move with robot. On up, objects at new row within beam also move up.
def hshift(objs, row, delta, beam, right=True):
    d={(r,s):c for c,r,s in objs}
    slots=sorted([s for c,r,s in objs if r==row and s<=beam], reverse=right)
    for s in slots:
        c=d.pop((row,s)); ns=s+delta
        # allow collisions overwrite for now, but blocking right
        if right and (row,ns) in d:
            d[(row,s)]=c
        else:
            d[(row,ns)]=c
    return tuple(sorted((c,r,s) for (r,s),c in d.items()))
def step(st,a):
    rob,b,objs=st
    if a==4:
        if b>=5:return st
        return rob,b+1,hshift(objs,rob,1,b+1,True)
    if a==3:
        if b<=0:return st
        return rob,b-1,hshift(objs,rob,-1,b,False)
    nr=rob+(-1 if a==1 else 1)
    if not 0<=nr<=4:return st
    moved=[]
    for c,r,s in objs:
        if s<=b and b>0 and (r==rob or (a==1 and r==nr)):
            moved.append((c,nr,s))
        else:moved.append((c,r,s))
    return nr,b,tuple(sorted(moved))
init=(2,0,tuple(sorted([(8,2,2),(9,3,2),('e',4,3)])))
def goal(st):
    rob,b,o=st
    d={c:(r,s) for c,r,s in o}
    return len(set(r for c,r,s in o))==1 and d[8][1]==2 and d[9][1]==3 and d['e'][1]==4
q=deque([init]); prev={init:None}; pa={}; found=None
while q:
    st=q.popleft()
    if goal(st):found=st;break
    for a in [1,2,3,4]:
        ns=step(st,a)
        if ns not in prev:
            prev[ns]=st;pa[ns]=a;q.append(ns)
print(len(prev),found)
if found:
    acts=[]
    while prev[found] is not None:
        acts.append(pa[found]);found=prev[found]
    print(acts[::-1])

